export function lineIcon(name, attrs) {
  var svg = ICONS[name];
  if (!svg) throw new Error('lineIcon: no line icon ' + name);
  if (!attrs) return svg;
  if (attrs.indexOf('=') < 0) return svg.replace('<svg', '<svg class="' + attrs + '"');
  if (attrs.indexOf('fill=') >= 0) svg = svg.replace(' fill="none"', '');
  if (attrs.indexOf('stroke=') >= 0) svg = svg.replace(' stroke="currentColor"', '');
  if (attrs.indexOf('stroke-width=') >= 0) svg = svg.replace(/ stroke-width="[^"]*"/, '');
  return svg.replace('<svg', '<svg ' + attrs);
}

export const TICK_STROKE = 'stroke-width="3.5"';
export function lineIconMask(name, attrs = '') {
  const svg = lineIcon(name, ('xmlns="http://www.w3.org/2000/svg" ' + attrs).trim()).replace('stroke="currentColor"', 'stroke="black"');
  return 'url("data:image/svg+xml,' + encodeURIComponent(svg) + '")';
}
